from qiskit import QuantumCircuit
from typing import List

def build_oracle(qc: QuantumCircuit, problem_qubits: List[int],
                 ancilla_qubits: List[int]) -> None:
    """
    Phase oracle for the vertex‑cover problem on the graph
    edges = [(0,3), (1,2), (2,3)] with the additional constraint
    that the cover size is at most k = 2.

    The satisfying assignments (written as x0 x1 x2 x3) are:
        1010  → vertices {0,2}
        0101  → vertices {1,3}
        0011  → vertices {2,3}

    The oracle flips the phase of exactly these basis states.
    """
    # We need only one clean ancilla for the multi‑controlled Z.
    phase_anc = ancilla_qubits[0]

    # Bit‑strings of the three valid solutions.
    solutions = [
        [1, 0, 1, 0],  # {0,2}
        [0, 1, 0, 1],  # {1,3}
        [0, 0, 1, 1],  # {2,3}
    ]

    for sol in solutions:
        # Apply X to qubits that should be 0 (negative controls).
        for i, bit in enumerate(sol):
            if bit == 0:
                qc.x(problem_qubits[i])

        # Multi‑controlled Z = H – multi‑controlled X – H.
        qc.h(phase_anc)
        qc.mcx(problem_qubits, phase_anc, mode='noancilla')
        qc.h(phase_anc)

        # Undo the X‑gates to restore the problem register.
        for i, bit in enumerate(sol):
            if bit == 0:
                qc.x(problem_qubits[i])
